function initPaletteOnly(){$$('.swatch').forEach((b,i)=>b.classList.toggle('active',i===state.palette))}
function resizeToPreset(){const p=preset($('#preset').value);canvas.width=p.w;canvas.height=p.h;render()}
function makeId(prefix){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`}
function selectedImage(){return state.images.find(image=>`image:${image.id}`===state.selectedLayerId)||null}
function loadUserImages(files){for(const file of files){if(!/^image\/(png|jpeg|webp)$/i.test(file.type)){setProjectStatus(`Unsupported image: ${file.name}. Use PNG, JPG or WebP.`);continue}const reader=new FileReader();reader.onload=()=>{const dataUrl=String(reader.result||''),image=new Image();image.onload=()=>{const item={id:makeId('image'),name:file.name||'Uploaded image',dataUrl,image,x:.72,y:.68,scale:1,rotation:0,opacity:1,outline:false};state.images.push(item);state.selectedLayerId=`image:${item.id}`;render()};image.onerror=()=>setProjectStatus(`Could not load image: ${file.name}`);image.src=dataUrl};reader.onerror=()=>setProjectStatus(`Could not read image: ${file.name}`);reader.readAsDataURL(file)}}
function removeSelectedImage(){const image=selectedImage();if(!image)return;state.images=state.images.filter(item=>item.id!==image.id);state.selectedLayerId='';render()}
function loadImageDataUrl(dataUrl,resetPosition=false){if(!dataUrl){state.image=null;state.imageDataUrl='';return}const img=new Image();img.onload=()=>{state.image=img;state.imageDataUrl=dataUrl;state.bg='image';if(resetPosition){state.imageX=.5;state.imageY=.5;state.imageScale=1}syncImageControls();$$('.bg').forEach(x=>x.classList.toggle('active',x.dataset.bg==='image'));render()};img.onerror=()=>setProjectStatus('The saved project image could not be loaded.');img.src=dataUrl}
function loadStock(key){if(state.stockImages[key])return;const img=new Image();img.crossOrigin='anonymous';img.onload=()=>{state.stockImages[key]=img;render()};img.onerror=()=>{$('#assetStatus').textContent='That stock background could not be loaded. Built-in backgrounds still work offline.'};img.src=stock[key]}
function drawCover(img,x=0,y=0,w=canvas.width,h=canvas.height,scale=1,cx=.5,cy=.5){if(!img)return;const r=Math.max(w/img.width,h/img.height)*scale,dw=img.width*r,dh=img.height*r;ctx.drawImage(img,x+(w-dw)*cx,y+(h-dh)*cy,dw,dh)}
function baseGradient(p){const w=canvas.width,h=canvas.height,g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,p[0]);g.addColorStop(.5,p[1]);g.addColorStop(1,p[0]);ctx.fillStyle=g;ctx.fillRect(0,0,w,h)}
function drawWaves(p){const w=canvas.width,h=canvas.height,v=state.variation;ctx.globalAlpha=.3;for(let i=0;i<18;i++){ctx.strokeStyle=i%2?p[2]:p[3];ctx.lineWidth=Math.max(2,w/500);ctx.beginPath();const y=(i/18)*h;ctx.moveTo(-w*.1,y);ctx.bezierCurveTo(w*.25,y+Math.sin(i+v)*h*.18,w*.7,y-Math.cos(i*.7+v)*h*.16,w*1.1,y+Math.sin(i)*h*.12);ctx.stroke()}ctx.globalAlpha=1}
function drawLaser(p){const w=canvas.width,h=canvas.height,cx=w*(.35+(state.variation%7)*.05),cy=h*.3;ctx.save();ctx.globalAlpha=.55;for(let i=0;i<28;i++){ctx.strokeStyle=i%3?p[2]:p[1];ctx.lineWidth=Math.max(2,w*.003);ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo((i/27)*w,h);ctx.stroke()}for(let y=cy;y<h;y+=h*.06){const t=(y-cy)/(h-cy);ctx.strokeStyle=p[3]+'66';ctx.beginPath();ctx.moveTo(cx*(1-t),y);ctx.lineTo(cx+(w-cx)*t,y);ctx.stroke()}ctx.restore()}
function drawTunnel(p){const w=canvas.width,h=canvas.height;ctx.save();ctx.translate(w/2,h/2);for(let i=0;i<16;i++){const t=i/16;ctx.strokeStyle=i%2?p[2]:p[1];ctx.globalAlpha=.12+.5*t;ctx.lineWidth=Math.max(2,w*.005);ctx.strokeRect(-w*.43*t,-h*.43*t,w*.86*t,h*.86*t)}ctx.restore();ctx.globalAlpha=1}
function drawSpeakers(p){const w=canvas.width,h=canvas.height;ctx.save();ctx.globalAlpha=.35;for(let r=0;r<5;r++)for(let c=0;c<4;c++){const x=w*(.14+c*.24),y=h*(.12+r*.2),rad=Math.min(w,h)*.075;ctx.strokeStyle=p[(r+c)%2?2:3];ctx.lineWidth=w*.006;ctx.beginPath();ctx.arc(x,y,rad,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(x,y,rad*.38,0,Math.PI*2);ctx.fillStyle=p[0];ctx.fill();ctx.stroke()}ctx.restore()}
function drawVinyl(p){const w=canvas.width,h=canvas.height,r=Math.min(w,h)*.42,x=w*.7,y=h*.55;ctx.save();ctx.globalAlpha=.72;ctx.fillStyle='#040508';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();for(let i=1;i<14;i++){ctx.strokeStyle=i%2?p[3]+'22':p[2]+'22';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,r*i/14,0,Math.PI*2);ctx.stroke()}ctx.fillStyle=p[1];ctx.beginPath();ctx.arc(x,y,r*.16,0,Math.PI*2);ctx.fill();ctx.fillStyle='#090b10';ctx.beginPath();ctx.arc(x,y,r*.025,0,Math.PI*2);ctx.fill();ctx.restore()}
