 if(effect==='lens-flare'){alpha(.9);for(const [x,y,r] of [[w*.78,h*.24,w*.095],[w*.2,h*.78,w*.06]]){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,p[3]+'dd');g.addColorStop(.16,p[2]+'99');g.addColorStop(1,p[2]+'00');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);alpha(.22);ctx.fillStyle=p[2];ctx.fillRect(0,y-h*.004,w,h*.008)}}
